// Diagnostic only. Does not replace the official parity test.
import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;
import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:crypto/crypto.dart';
import 'package:flutter/foundation.dart' show debugPrint;
import 'package:flutter/services.dart' show rootBundle;
import 'package:flutter_test/flutter_test.dart';
import 'package:frontend/services/classifier.dart';
import 'package:integration_test/integration_test.dart';
import 'package:tflite_flutter/tflite_flutter.dart';

class _Sample {
  const _Sample(this.name, this.jpg, this.tensor, this.scores);
  final String name;
  final String jpg;
  final String tensor;
  final List<double> scores;
}

List<double> _predict(Interpreter interpreter, Float32List tensor) {
  final output = [List<double>.filled(3, 0)];
  interpreter.run(tensor.buffer, output);
  return output.first;
}

double _delta(List<double> a, List<double> b) {
  var delta = 0.0;
  for (var i = 0; i < a.length; i++) {
    delta = math.max(delta, (a[i] - b[i]).abs());
  }
  return delta;
}

int _winner(List<double> scores) {
  var winner = 0;
  for (var i = 1; i < scores.length; i++) {
    if (scores[i] > scores[winner]) winner = i;
  }
  return winner;
}

Future<Uint8List> _decodeNative(Uint8List photo) async {
  final codec = await ui.instantiateImageCodec(photo);
  try {
    final frame = await codec.getNextFrame();
    try {
      final data = await frame.image.toByteData(format: ui.ImageByteFormat.png);
      if (data == null) throw StateError('No se pudo obtener PNG de diagnóstico.');
      return data.buffer.asUint8List(data.offsetInBytes, data.lengthInBytes);
    } finally {
      frame.image.dispose();
    }
  } finally {
    codec.dispose();
  }
}

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
  testWidgets('Diagnostico de paridad: tensor identico, JPG Dart y JPG nativo', (_) async {
    final asset = await rootBundle.load('assets/models/tomatolens_v1.tflite');
    final model = asset.buffer.asUint8List(asset.offsetInBytes, asset.lengthInBytes);
    expect(sha256.convert(model).toString(), _expectedSha);
    final interpreter = Interpreter.fromBuffer(model, options: InterpreterOptions()..threads = 2);
    var worstSameTensor = 0.0, worstDart = 0.0, worstNative = 0.0;
    try {
      for (final sample in _samples) {
        final photo = base64Decode(sample.jpg);
        final exactBytes = Uint8List.fromList(zlib.decode(base64Decode(sample.tensor)));
        final exact = Float32List.view(exactBytes.buffer);
        final dart = preprocessImage(photo);
        final native = preprocessImage(await _decodeNative(photo));
        final sameScores = _predict(interpreter, exact);
        final dartScores = _predict(interpreter, dart);
        final nativeScores = _predict(interpreter, native);
        final sameDelta = _delta(sameScores, sample.scores);
        final dartDelta = _delta(dartScores, sample.scores);
        final nativeDelta = _delta(nativeScores, sample.scores);
        worstSameTensor = math.max(worstSameTensor, sameDelta);
        worstDart = math.max(worstDart, dartDelta);
        worstNative = math.max(worstNative, nativeDelta);
        debugPrint('PARIDAD ${sample.name} | puntuacion: tensor=${sameDelta.toStringAsFixed(6)} '
          'Dart=${dartDelta.toStringAsFixed(6)} nativo=${nativeDelta.toStringAsFixed(6)} '
          '| pixeles: Dart=${_delta(dart, exact).toStringAsFixed(3)} '
          'nativo=${_delta(native, exact).toStringAsFixed(3)} '
          '| clase Python/tensor/Dart/nativo: ${_winner(sample.scores)}/'
          '${_winner(sameScores)}/${_winner(dartScores)}/${_winner(nativeScores)}');
      }
      debugPrint('RESUMEN_PARIDAD casos=${_samples.length} tensor=$worstSameTensor '
        'Dart=$worstDart nativo=$worstNative');
    } finally {
      interpreter.close();
    }
  });
}


